const std = @import("std");

pub const TensorError = error{
    IncompatibleShapes,
    OutOfMemory,
    InvalidDimension,
};

pub const Shape = struct {
    dims: []const usize,

    pub fn init(allocator: std.mem.Allocator, dims: []const usize) !Shape {
        const new_dims = try allocator.alloc(usize, dims.len);
        @memcpy(new_dims, dims);
        return Shape{ .dims = new_dims };
    }
};

pub const Tensor = struct {
    allocator: std.mem.Allocator,
    shape: Shape,
    data: []f32,

    pub fn init(allocator: std.mem.Allocator, shape: Shape) !Tensor {
        var size: usize = 1;
        for (shape.dims) |d| size *= d;
        const data = try allocator.alloc(f32, size);
        @memset(data, 0);
        return Tensor{
            .allocator = allocator,
            .shape = shape,
            .data = data,
        };
    }

    pub fn deinit(self: *Tensor) void {
        self.allocator.free(self.data);
        self.allocator.free(self.shape.dims);
    }

    pub fn matmul(a: Tensor, b: Tensor, out: *Tensor) !void {
        if (a.shape.dims.len != 2 or b.shape.dims.len != 2) return TensorError.InvalidDimension;
        const m = a.shape.dims[0];
        const k = a.shape.dims[1];
        const n = b.shape.dims[1];
        if (k != b.shape.dims[0] or out.shape.dims[0] != m or out.shape.dims[1] != n) return TensorError.IncompatibleShapes;

        for (0..m) |i| {
            for (0..n) |j| {
                var sum: f32 = 0;
                for (0..k) |l| {
                    sum += a.data[i * k + l] * b.data[l * n + j];
                }
                out.data[i * n + j] = sum;
            }
        }
    }
};
