```lobster
import std
import vec

enum Token:
    TOKEN_EOF = 0
    TOKEN_ID = 1
    TOKEN_NUM = 2
    TOKEN_OP = 3

class Tokenizer:
    source: string
    pos: int = 0
    vocab: [string] = []

    def next_token() -> int, string:
        while pos < source.length and source[pos] <= 32:
            pos++
        if pos >= source.length: return TOKEN_EOF, ""

        let start = pos
        if (source[pos] >= 'a' and source[pos] <= 'z') or (source[pos] >= 'A' and source[pos] <= 'Z'):
            while pos < source.length and ((source[pos] >= 'a' and source[pos] <= 'z') or (source[pos] >= 'A' and source[pos] <= 'Z') or (source[pos] >= '0' and source[pos] <= '9')):
                pos++
            return TOKEN_ID, source.substring(start, pos - start)

        if source[pos] >= '0' and source[pos] <= '9':
            while pos < source.length and (source[pos] >= '0' and source[pos] <= '9'):
                pos++
            return TOKEN_NUM, source.substring(start, pos - start)

        pos++
        return TOKEN_OP, source.substring(start, 1)

    def build_vocab(data: [string]):
        for data:
            let t = Tokenizer { source: _ }
            var type, val = t.next_token()
            while type != TOKEN_EOF:
                if not vocab.contains(val):
                    vocab.push(val)
                type, val = t.next_token()
