const std = @import("std");

pub const TensorError = error{
    IncompatibleShapes,
    OutOfMemory,
    InvalidDimension,
};

pub const Tensor = struct {
    data: []f32,
    shape: []const usize,
    allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator, shape: []const usize) !Tensor {
        if (shape.len == 0) return TensorError.InvalidDimension;
        var size: usize = 1;
        for (shape) |dim| {
            if (dim == 0) return TensorError.InvalidDimension;
            size *= dim;
        }
        const data = try allocator.alloc(f32, size);
        @memset(data, 0);
        return Tensor{
            .data = data,
            .shape = shape,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *const Tensor) void {
        self.allocator.free(self.data);
    }

    pub fn matmul(a: Tensor, b: Tensor, res: *Tensor) !void {
        if (a.shape.len != 2 or b.shape.len != 2 or res.shape.len != 2) return TensorError.IncompatibleShapes;
        if (a.shape[1] != b.shape[0] or res.shape[0] != a.shape[0] or res.shape[1] != b.shape[1]) {
            return TensorError.IncompatibleShapes;
        }
        const M = a.shape[0];
        const K = a.shape[1];
        const N = b.shape[1];
        var i: usize = 0;
        while (i < M) : (i += 1) {
            var j: usize = 0;
            while (j < N) : (j += 1) {
                var sum: f32 = 0;
                var k: usize = 0;
                while (k < K) : (k += 1) {
                    sum += a.data[i * K + k] * b.data[k * N + j];
                }
                res.data[i * N + j] = sum;
            }
        }
    }
};

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    const allocator = gpa.allocator();
    defer _ = gpa.deinit();

    const shape = [_]usize{ 2, 2 };
    var a = try Tensor.init(allocator, &shape);
    defer a.deinit();
    var b = try Tensor.init(allocator, &shape);
    defer b.deinit();
    var res = try Tensor.init(allocator, &shape);
    defer res.deinit();

    a.data[0] = 1.0; a.data[1] = 2.0;
    a.data[2] = 3.0; a.data[3] = 4.0;
    b.data[0] = 5.0; b.data[1] = 6.0;
    b.data[2] = 7.0; b.data[3] = 8.0;

    try Tensor.matmul(a, b, &res);
