```inko
import std.string.String
import std.collections.List
import std.ascii.Char

class Token {
  let @type: String
  let @value: String

  fn static new(type: String, value: String) -> Token {
    Token(@type: type, @value: value)
  }

  fn type -> String { @type }
  fn value -> String { @value }
}

class Tokenizer {
  let @input: String
  let @position: Int
  let @size: Int

  fn static new(input: String) -> Tokenizer {
    Tokenizer(@input: input, @position: 0, @size: input.size)
  }

  fn tokenize -> List[Token] {
    let tokens = List.new
    while @position < @size {
      let char = @input.get(@position).unwrap
      if char == " " or char == "\n" or char == "\t" {
        @position += 1
        next
      }
      if is_digit(char) {
        tokens.push(read_number)
      } else if is_alpha(char) {
        tokens.push(read_word)
      } else {
        @position += 1
      }
    }
    tokens
  }

  fn read_number -> Token {
    let start = @position
    while @position < @size and is_digit(@input.get(@position).unwrap) {
      @position += 1
    }
    Token.new("NUMBER", @input.slice(start, @position - start))
  }

  fn read_word -> Token {
    let start = @position
    while @position < @size and is_alpha(@input.get(@position).unwrap) {
      @position += 1
    }
    Token.new("WORD", @input.slice(start, @position - start))
  }

  fn is_digit(c: String) -> Bool {
    c >= "0" and c <= "9"
  }

  fn is_alpha(c: String) -> Bool {
    (c >= "a" and c <= "z") or (c >= "A" and c <= "Z")
  }
}
