const std = @import("std");

pub const TensorError = error{
    IncompatibleShapes,
    OutOfMemory,
    InvalidDimension,
    IndexOutOfBounds,
};

pub const Tensor = struct {
    data: []f32,
    shape: []usize,
    allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator, shape: []const usize) !Tensor {
        if (shape.len == 0) return TensorError.InvalidDimension;

        var total_size: usize = 1;
        var shape_copy = try allocator.alloc(usize, shape.len);

        for (shape, 0..) |dim, i| {
            if (dim == 0) return TensorError.InvalidDimension;
            total_size *= dim;
            shape_copy[i] = dim;
        }

        const data = try allocator.alloc(f32, total_size);
        @memset(data, 0.0);

        return Tensor{
            .data = data,
            .shape = shape_copy,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *Tensor) void {
        self.allocator.free(self.data);
        self.allocator.free(self.shape);
    }

    pub fn get(self: *const Tensor, indices: []const usize) !f32 {
        if (indices.len != self.shape.len) return TensorError.InvalidDimension;

        var flat_index: usize = 0;
        var multiplier: usize = 1;

        var i: usize = self.shape.len;
        while (i > 0) {
            i -= 1;
            if (indices[i] >= self.shape[i]) return TensorError.IndexOutOfBounds;
            flat_index += indices[i] * multiplier;
            multiplier *= self.shape[i];
        }

        return self.data[flat_index];
    }

    pub fn set(self: *Tensor, indices: []const usize, value: f32) !void {
        if (indices.len != self.shape.len) return TensorError.InvalidDimension;

        var flat_index: usize = 0;
        var multiplier: usize = 1;

        var i: usize = self.shape.len;
        while (i > 0) {
            i -= 1;
            if (indices[i] >= self.shape[i]) return TensorError.IndexOutOfBounds;
            flat_index += indices[i] * multiplier;
            multiplier *= self.shape[i];
        }

        self.data[flat_index] = value;
    }
};

pub const Tokenizer = struct {
    allocator: std.mem.Allocator,
    vocab: std.AutoHashMap([]const u8, u32),
    next_id: u32,

    pub fn init(allocator: std.mem.Allocator) Tokenizer {
        return Tokenizer{
            .allocator = allocator,
            .vocab = std.AutoHashMap([]const u8, u32).init(allocator),
            .next_id = 0,
        };
    }

    pub fn deinit(self: *Tokenizer) void {
        var iter = self.vocab.keyIterator();
        while (iter.next()) |key_ptr| {
            self.allocator.free(key_ptr.*);
        }
        self.vocab.deinit();
    }

    pub fn train(self: *Tokenizer, data: []const u8) !void {
        var start: usize = 0;
        var end: usize = 0;
        while (end < data.len) {
            if (data[end] == ' ') {
                if (end > start) {
                    const word = data[start..end];
                    if (!self.vocab.contains(word)) {
                        const word_copy = try self.allocator.dupe(u8, word);
                        try self.vocab.put(word_copy, self.next_id);
                        self.next_id += 1;
                    }
                }
                start = end + 1;
            }
            end += 1;
        }
        if (end > start) {
             const word = data[start..end];
             if (!self.vocab.contains(word)) {
                const word_copy = try self.allocator.dupe(u8, word);
                try self.vocab.put(word_copy, self.next_id);
                self.next_id += 1;
             }
        }
    }

    pub fn encode(self: *Tokenizer, text: []const u8) !std.ArrayList(u32) {
        var tokens = std.ArrayList(u32).init(self.allocator);
        var start: usize = 0;
        var end: usize = 0;

        while (end < text.len) {
            if (text[end] == ' ') {
                if (end > start) {
                    const word = text[start..end];
                    if (self.vocab.get(word)) |id| {
                        try tokens.append(id);
                    }
                }
                start = end + 1;
            }
            end += 1;
        }
        if (end > start) {
            const word = text[start..end];
            if (self.vocab.get(word)) |id| {
                try tokens.append(id);
            }
        }
        return tokens;
    }
};

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const shape = [_]usize{2, 2};
    var tensor = try Tensor.init(allocator, &shape);
    defer tensor.deinit();

    const idx = [_]usize{0, 1};
    try tensor.set(&idx, 3.14);

    var tokenizer = Tokenizer.init(allocator);
    defer tokenizer.deinit();

    try tokenizer.train("root level intelligence");
    var encoded = try tokenizer.encode("root intelligence");
    defer encoded.deinit();
}
