element Point
    position : vector(float)[1]
    velocity : vector(float)[1]
    mass     : float
end

element Spring
    stiffness : float
    rest_length : float
end

extern points  : set{Point}
extern springs : set{Spring}(points, points)

func compute_forces(p : Point, s : Spring, neighbor : Point) -> vector(float)[1]
    var dist_vec = p.position - neighbor.position
    var dist = norm(dist_vec)
    var force_mag = s.stiffness * (dist - s.rest_length)
    return (dist_vec / dist) * force_mag
end

proc update_system(dt : float)
    for s in springs
        var p1 = s.endpoints(0)
        var p2 = s.endpoints(1)
        var f = compute_forces(p1, s, p2)

        p1.velocity = p1.velocity - (f / p1.mass) * dt
        p2.velocity = p2.velocity + (f / p2.mass) * dt
    end

    for p in points
        p.position = p.position + p.velocity * dt
    end
end
