class DeploymentAgent {
    let @port: Int
    let @running: Bool

    fn static new(port: Int) -> DeploymentAgent {
        DeploymentAgent(@port: port, @running: true)
    }

    fn start {
        let listener = TcpListener.new("0.0.0.0", @port).expect("Failed to bind")
        while @running {
            match listener.accept {
                case Ok(socket) -> handle_connection(socket)
                case Error(_) -> @running = false
            }
        }
    }

    fn handle_connection(socket: TcpSocket) {
        let response = "HTTP/1.1 200 OK\r\nContent-Type: text/plain\r\n\r\nSystem Online"
        socket.write(response.to_bytes).expect("Write failed")
        socket.close
    }
}

